import json
import numpy as np

# Load both JSONs
with open('/root/autodl-tmp/vla-ssd/results/action_trajectory_analysis.json') as f:
    inst = json.load(f)
with open('/root/autodl-tmp/vla-ssd/results/action_trajectory_control.json') as f:
    ctrl = json.load(f)

dim_labels = ["dx", "dy", "dz", "roll", "pitch", "yaw", "gripper"]

# Extract per-dim MAE (already stored as per_dim_action_shift.means)
inst_mae = inst['main_metrics']['per_dim_action_shift']['means']
ctrl_mae = ctrl['main_metrics']['per_dim_action_shift']['means']
inst_std = inst['main_metrics']['per_dim_action_shift']['stds']
ctrl_std = ctrl['main_metrics']['per_dim_action_shift']['stds']

# Per-task per-dim MAE
task_names = list(inst['per_task'].keys())
inst_per_task = {}
ctrl_per_task = {}
for t in task_names:
    inst_per_task[t] = {
        "per_dim_mae": inst['per_task'][t]['per_dim_shift']['means'],
        "per_dim_mae_std": inst['per_task'][t]['per_dim_shift']['stds'],
    }
    ctrl_per_task[t] = {
        "per_dim_mae": ctrl['per_task'][t]['per_dim_shift']['means'],
        "per_dim_mae_std": ctrl['per_task'][t]['per_dim_shift']['stds'],
    }

# Compute ratio (instruction / control) per dim
ratio = [i / c if c > 0 else float('inf') for i, c in zip(inst_mae, ctrl_mae)]

# Build output
output = {
    "instruction_24h": {
        "per_dim_mae": inst_mae,
        "per_dim_mae_std": inst_std,
        "per_dim_mae_labels": dim_labels,
        "cosine_similarity": {
            "status": "not_computable",
            "reason": "Raw per-sample action vectors not stored in JSON; only aggregated statistics available"
        },
        "per_task": inst_per_task
    },
    "control_8h": {
        "per_dim_mae": ctrl_mae,
        "per_dim_mae_std": ctrl_std,
        "per_dim_mae_labels": dim_labels,
        "cosine_similarity": {
            "status": "not_computable",
            "reason": "Raw per-sample action vectors not stored in JSON; only aggregated statistics available"
        },
        "per_task": ctrl_per_task
    },
    "comparison": {
        "per_dim_mae_ratio_inst_over_ctrl": ratio,
        "per_dim_mae_ratio_labels": dim_labels,
        "cosine_sim_difference": {
            "status": "not_computable",
            "reason": "Raw per-sample action vectors not stored in JSON"
        },
        "summary": {
            "most_affected_dims_by_instruction_ablation": [],
            "ratio_interpretation": "Values > 1 mean instruction-head ablation causes larger shift than control-head ablation on that dimension"
        }
    },
    "metadata": {
        "source_files": [
            "action_trajectory_analysis.json",
            "action_trajectory_control.json"
        ],
        "note": "per_dim_mae extracted from per_dim_action_shift.means (mean absolute shift between baseline and ablated actions). Cosine similarity requires raw per-sample action vectors which were not saved."
    }
}

# Identify most affected dims (ratio > 2)
ranked = sorted(enumerate(ratio), key=lambda x: x[1], reverse=True)
output["comparison"]["summary"]["most_affected_dims_by_instruction_ablation"] = [
    {"dim": dim_labels[i], "ratio": round(r, 3), "inst_mae": round(inst_mae[i], 6), "ctrl_mae": round(ctrl_mae[i], 6)}
    for i, r in ranked
]

with open('/root/autodl-tmp/vla-ssd/results/action_metrics_extended.json', 'w') as f:
    json.dump(output, f, indent=2)

print("Saved action_metrics_extended.json")
print("\nPer-dim MAE ratio (instruction/control):")
for i, (dim, r) in enumerate(zip(dim_labels, ratio)):
    print(f"  {dim:8s}: inst={inst_mae[i]:.6f}  ctrl={ctrl_mae[i]:.6f}  ratio={r:.3f}")
